-- notificationChannels
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('LINE', 'LINE', '{"th":"ไลน์","en":"LINE","ja":"LINE"}', 'LINE personal ID or LINE Official Account user ID', 'Dominant messaging channel in Thailand (90%+ penetration). Highest engagement.', '{"th":"ช่องทางรับส่งข้อความหลักในประเทศไทย มีการใช้งานมากกว่า 90 เปอร์เซ็นต์และมีการมีส่วนร่วมสูงสุด","en":"Dominant messaging channel in Thailand (90%+ penetration). Highest engagement.","ja":"タイで圧倒的に使われているメッセージ手段（普及率90%以上）。反応率が最も高い。"}', 1) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('EMAIL', 'Email', '{"th":"อีเมล","en":"Email","ja":"メール"}', 'RFC 5322 email address', 'Universal but lower engagement in Thailand. Good for digests and receipts.', '{"th":"ใช้ได้ทั่วไปแต่มีการมีส่วนร่วมในไทยต่ำกว่า เหมาะสำหรับสรุปข้อมูลและใบเสร็จ","en":"Universal but lower engagement in Thailand. Good for digests and receipts.","ja":"誰でも使えるがタイでは反応率が低い。ダイジェストや控えの送付に適する。"}', 2) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('SMS', 'SMS', '{"th":"เอสเอ็มเอส","en":"SMS","ja":"SMS"}', 'E.164 phone number', 'Reliable delivery; cost per message. Good for OTP and critical alerts.', '{"th":"ส่งถึงผู้รับได้อย่างน่าเชื่อถือ แต่มีค่าใช้จ่ายต่อข้อความ เหมาะสำหรับรหัส OTP และการแจ้งเตือนสำคัญ","en":"Reliable delivery; cost per message. Good for OTP and critical alerts.","ja":"確実に届くが1通ごとに費用がかかる。認証コードや重要な通知に適する。"}', 3) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('PUSH', 'Push', '{"th":"การแจ้งเตือนแบบ Push","en":"Push","ja":"プッシュ通知"}', 'Web Push subscription token (PWA)', 'Requires PWA installation. Free at scale; limited reach until adoption grows.', '{"th":"ต้องติดตั้ง PWA ไม่มีค่าใช้จ่ายเมื่อใช้งานในปริมาณมาก แต่การเข้าถึงยังจำกัดจนกว่าจะมีผู้ติดตั้งเพิ่ม","en":"Requires PWA installation. Free at scale; limited reach until adoption grows.","ja":"PWAのインストールが必要。大量配信でも無料だが、普及するまで届く範囲は限られる。"}', 4) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO notification_channel (code, name_en, names, address_format, description_en, descriptions, sort) VALUES ('IN_APP', 'In-app', '{"th":"การแจ้งเตือนในแอป","en":"In-app","ja":"アプリ内"}', 'Internal user ID (delivered when user opens app/site)', 'Always works for signed-in users; only seen when user is active.', '{"th":"ใช้งานได้เสมอสำหรับผู้ที่ลงชื่อเข้าใช้ แต่จะแสดงเมื่อผู้ใช้กำลังใช้งานแอปหรือเว็บไซต์","en":"Always works for signed-in users; only seen when user is active.","ja":"ログイン中のユーザーには必ず届くが、利用中でなければ見られない。"}', 5) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, address_format = excluded.address_format, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;

