INSERT INTO role (code, name_en, names, description_en, descriptions, sort) VALUES ('ADMIN', 'Admin', '{"th":"ผู้ดูแลระบบ","en":"Admin","ja":"管理者"}', 'Internal staff managing the platform — full write access across all data', '{"th":"เจ้าหน้าที่ภายในที่ดูแลแพลตฟอร์มและมีสิทธิ์เขียนข้อมูลทั้งหมด","en":"Internal staff managing the platform — full write access across all data","ja":"プラットフォームを運営する内部スタッフ — 全データへの書き込み権限"}', 1) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO role (code, name_en, names, description_en, descriptions, sort) VALUES ('ORGANIZER', 'Organizer', '{"th":"ผู้จัดการแข่งขัน","en":"Organizer","ja":"主催者"}', 'Creates and runs tournaments leagues camps showcases', '{"th":"สร้างและจัดทัวร์นาเมนต์ ลีก ค่ายฝึก และกิจกรรมแสดงผลงาน","en":"Creates and runs tournaments leagues camps showcases","ja":"大会・リーグ・キャンプ・ショーケースを作成し運営する"}', 2) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO role (code, name_en, names, description_en, descriptions, sort) VALUES ('COACH', 'Coach', '{"th":"โค้ช","en":"Coach","ja":"コーチ"}', 'Manages a team — roster registration attendance', '{"th":"จัดการทีม การลงทะเบียนรายชื่อผู้เล่น และการบันทึกการเข้าร่วม","en":"Manages a team — roster registration attendance","ja":"チームを管理する — ロースター・登録・出席"}', 3) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO role (code, name_en, names, description_en, descriptions, sort) VALUES ('PLAYER', 'Player', '{"th":"ผู้เล่น","en":"Player","ja":"選手"}', 'Individual athlete — own profile registrations stats', '{"th":"นักกีฬารายบุคคลที่จัดการโปรไฟล์ การลงทะเบียน และสถิติของตนเอง","en":"Individual athlete — own profile registrations stats","ja":"個人の競技者 — 自分のプロフィール・登録・スタッツ"}', 4) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO role (code, name_en, names, description_en, descriptions, sort) VALUES ('SPECTATOR', 'Spectator', '{"th":"ผู้ชม","en":"Spectator","ja":"観戦者"}', 'Read-only follower — parents fans casual viewers', '{"th":"ผู้ติดตามที่อ่านข้อมูลได้อย่างเดียว เช่น ผู้ปกครอง แฟนกีฬา และผู้ชมทั่วไป","en":"Read-only follower — parents fans casual viewers","ja":"閲覧のみのフォロワー — 保護者・ファン・一般の視聴者"}', 5) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO role (code, name_en, names, description_en, descriptions, sort) VALUES ('REFEREE', 'Referee', '{"th":"ผู้ตัดสิน","en":"Referee","ja":"審判"}', 'Certified official — score entry match status', '{"th":"เจ้าหน้าที่ผู้ได้รับการรับรองที่บันทึกคะแนนและสถานะการแข่งขัน","en":"Certified official — score entry match status","ja":"公認審判 — スコア入力と試合状況"}', 6) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;

