-- userStatuses
INSERT INTO user_status (code, name_en, names, description_en, descriptions, sort) VALUES ('ACTIVE', 'Active', '{"th":"ใช้งานอยู่","en":"Active","ja":"有効"}', 'Account is fully active and can use the platform', '{"th":"บัญชีเปิดใช้งานเต็มรูปแบบและสามารถใช้แพลตฟอร์มได้","en":"Account is fully active and can use the platform","ja":"アカウントは有効で、プラットフォームを利用できます"}', 1) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO user_status (code, name_en, names, description_en, descriptions, sort) VALUES ('PENDING_APPROVAL', 'Pending Approval', '{"th":"รออนุมัติ","en":"Pending Approval","ja":"承認待ち"}', 'Account exists but is waiting for admin approval (e.g. REFEREE awaiting BAT certification verification)', '{"th":"มีบัญชีแล้วแต่กำลังรอการอนุมัติจากผู้ดูแลระบบ เช่น ผู้ตัดสินที่รอการตรวจสอบการรับรอง BAT","en":"Account exists but is waiting for admin approval (e.g. REFEREE awaiting BAT certification verification)","ja":"アカウントは存在するが管理者の承認待ち（例：BAT認定の確認を待つ審判）"}', 2) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO user_status (code, name_en, names, description_en, descriptions, sort) VALUES ('SUSPENDED', 'Suspended', '{"th":"ระงับชั่วคราว","en":"Suspended","ja":"一時停止"}', 'Account is temporarily suspended by admin', '{"th":"บัญชีถูกระงับชั่วคราวโดยผู้ดูแลระบบ","en":"Account is temporarily suspended by admin","ja":"管理者により一時的に停止されています"}', 3) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;
INSERT INTO user_status (code, name_en, names, description_en, descriptions, sort) VALUES ('DEACTIVATED', 'Deactivated', '{"th":"ปิดใช้งาน","en":"Deactivated","ja":"無効化"}', 'Account is permanently deactivated', '{"th":"บัญชีถูกปิดใช้งานถาวร","en":"Account is permanently deactivated","ja":"アカウントは永久に無効化されています"}', 4) ON CONFLICT(code) DO UPDATE SET name_en = excluded.name_en, names = excluded.names, description_en = excluded.description_en, descriptions = excluded.descriptions, sort = excluded.sort;

